style.css:
@-moz-document domain("youtube.com") {
/* Arka plan görsel */
  html, body, ytd-app {
    background: url("https://preview.redd.it/made-this-dexter-pc-wallpaper-wanted-to-share-it-v0-vpphyhydmzbe1.png?auto=webp&s=8c25672d2806443ae9038287de01c27b5f5feec6") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Şeffaflık her yere */
  *, *::before, *::after {
    background: transparent !important;
    background-color: transparent !important;
    box-shadow: none !important;
    border-color: rgba(255, 0, 0, 0.4) !important; /* hafif neon kenarlıklar */
  }

  /* Video alanına dramatik gölge */
  #player, ytd-player, #movie_player {
    box-shadow: 0 0 40px rgba(255, 0, 0, 0.7) !important;
    background-color: black !important;
  }

  /* Yazılara kırmızımsı gölgeler */
  h1, h2, h3, h4, span, yt-formatted-string, a, p {
    text-shadow: 0 0 4px #ff0000, 0 0 10px #ff0040 !important;
    color: #fff !important;
  }

  /* Butonlar – neon kırmızı efekti */
  button, ytd-button-renderer, paper-button, .yt-spec-button-shape-next {
    color: #ff0000 !important;
    border: 1px solid #ff0000 !important;
    text-shadow: 0 0 4px #ff0000;
    box-shadow: 0 0 12px #ff0000 !important;
    background-color: rgba(0, 0, 0, 0.3) !important;
    transition: all 0.3s ease-in-out;
  }

  button:hover, ytd-button-renderer:hover, .yt-spec-button-shape-next:hover {
    background-color: rgba(255, 0, 0, 0.1) !important;
    box-shadow: 0 0 20px #ff0033 !important;
  }

  /* İmleç video alanındayken neon kırmızı olsun */
  #movie_player:hover {
    cursor: url("https://cur.cursors-4u.net/cursors/cur-11/cur1013.cur"), auto !important;
  }

  /* Scrollbar stili (isteğe bağlı) */
  ::-webkit-scrollbar {
    width: 8px;
    background: transparent;
  }
  ::-webkit-scrollbar-thumb {
    background-color: rgba(255, 0, 0, 0.4);
    border-radius: 10px;
  }
}
